#!/usr/bin/env python3
"""Build provenance, validation and publication manifest for metadata-only deliverables."""
import json,pathlib,hashlib
p=pathlib.Path(__file__).resolve().parent
def load(n):return json.loads((p/n).read_text())
def save(n,x):(p/n).write_text(json.dumps(x,indent=2)+'\n')
r=load('search-log.json');c=load('candidate-verification.json');s=load('summary.json');s['verification_completed_utc']=c['requests'][-1]['completed_utc'];save('summary.json',s)
old={x['nctId']:x for x in load('baseline-search-log.json')['registry_records']}
rows=[json.loads(x) for x in (p/'registry-evidence.jsonl').read_text().splitlines()]
for x in c['registry']:
 n=x['id'];keys=['status','design','hasResults'];before=old.get(n)
 rows.append({'date_checked':'2026-10-19','id':'nct:'+n,'evidence_type':'registry_out_of_window_recheck','source_url':'https://clinicaltrials.gov/study/'+n,'status':x['status'],'has_results':x['hasResults'],'new_result':False,'compared_fields':keys if before else [],'changes':{k:{'before':before.get(k),'after':x.get(k)} for k in keys if before.get(k)!=x.get(k)} if before else None,'decision':'Official last posting predates October 17–19 window. Protocol status is not a treatment result.'})
(p/'registry-evidence.jsonl').write_text(''.join(json.dumps(x)+'\n' for x in rows))
queries=['Tourette "October 18" "2026" research','Tourette "October 19" "2026" trial','site.medrxiv.org Tourette October 2026','site.biorxiv.org Tourette October 2026','"Tourette" research October 2026 adult','"tic disorder" research October 2026','site.clinicaltrials.gov "Tourette" "2026-10-18"','site.isrctn.com Tourette 2026','"Tourette" "2026" "October" randomized negative trial','"Tourette" "2026" "October" pain adult burden']
save('discovery-log.json',{'date':'2026-10-19','tool':'web search','time_interval_utc':['03:07:22','03:07:48'],'exact_queries':queries,'recency_days':{'indices_4_5_8_9':3},'count_limit':'Search engine supplied combined ranked responses, not enumerable database totals; no completeness claim. Ten queries in three calls.','screening':'No verified in-window primary result. Older review/hypothesis/registry/preprint leads were classified using primary sources; unrelated legal-trial and social results excluded without retained details.','selected_sources':[{'url':'https://www.frontiersin.org/journals/psychiatry/articles/10.3389/fpsyt.2026.1948442/full','decision':'Publisher identifies Hypothesis and Theory, published October 2.'},{'url':'https://www.frontiersin.org/journals/child-and-adolescent-psychiatry/articles/10.3389/frcha.2026.1936806/full','decision':'Publisher identifies systematic review, published October 2.'},{'url':'https://www.medrxiv.org/content/10.64898/2026.09.29.26364036v1','decision':'Preprint posted October 1, outside window; no new version verified.'},{'url':'https://www.biorxiv.org/content/10.64898/2026.07.27.740916v1','decision':'Preprint posted July 28, outside window; no new version verified.'},{'url':'https://clinicaltrials.ucsf.edu/trial/NCT07839377','decision':'Institutional registry lead, checked against official CTgov API.'}], 'github_exact_identifier_searches':{'repository':'dotjade/project-neurofreedom','time_utc':'03:08:58','queries':['40977255','41621322','1948442','1936806'],'returned_results_each':0,'limit':'Search absence does not establish cohort independence.'}})
save('provenance.json',{'repository':'https://github.com/dotjade/project-neurofreedom','tree_sha_at_read':'00f5e25592b3ab2a15f5485053358ea9356d97a5','retrieval':'GitHub connector, main branch, October 19 03:06–03:07 UTC','inputs_read':['RESEARCH_PROTOCOL.md','evidence.jsonl','updates/2026-10-18/report.md','updates/2026-10-18/scan_sources.py','updates/2026-10-18/scan_supplement.py','updates/2026-10-18/check_isrctn.py','updates/2026-10-18/build_results.py','updates/2026-10-18/search-log.json','updates/2026-10-18/supplement-selected-metadata.json'],'code_adaptation':'Previous bounded scan updated to October 17–19 inclusive; near-entry window October 18–19; ISRCTN exclusive end October 20. No source text persisted.','baseline_files':{'baseline-metadata.json':'Selected prior identifiers, PubMed dates/corrections and preprint DOI/version keys, required by scan_sources.py.','baseline-supplement.json':'Prior selected registry metadata, required by build_results.py.','baseline-search-log.json':'Prior query metadata needed only for finalize.py registry comparison.'},'privacy':'No person-level observations, contact fields, full papers or abstract bodies retained.'})
checks={'pubmed_ids_unique':len(set(x['pmid'] for x in r['pubmed']['date_type_correction_screen']))==12,'pubmed_counts_match':sum(x['count'] for x in r['pubmed']['queries'])==21,'all_pubmed_decided':all('Pending' not in x['screening_decision'] for x in r['pubmed']['date_type_correction_screen']),'new_primary_intentionally_empty':(p/'primary-evidence.jsonl').stat().st_size==0,'preprint_counts_match':sum(x['unique_doi_versions'] for x in r['preprints'])==134,'preprint_pagination_complete':all(x['pagination_complete_for_observed_response'] for x in r['preprints']),'core_no_errors':not any(x.get('error') for x in r['retrieval_requests']),'candidate_no_errors':not any(x.get('error') for x in c['requests']),'registries_no_new_results':all(not x['has_results'] for x in rows)}
assert all(checks.values()),checks
save('validation.json',{'checks':checks,'result':'PASS','scope':'Structural/count/provenance checks, not independent clinical peer review.'})
files=['report.md','summary.json','search-log.json','scan_sources.py','scan_supplement.py','check_isrctn.py','verify_candidates.py','build_results.py','finalize.py','baseline-metadata.json','baseline-supplement.json','baseline-search-log.json','supplement-selected-metadata.json','isrctn-control.json','candidate-verification.json','primary-evidence.jsonl','secondary-screening.jsonl','historical-leads.jsonl','registry-evidence.jsonl','discovery-log.json','provenance.json','validation.json']
save('manifest.json',{'destination_prefix':'updates/2026-10-19/','files':[{'local':n,'destination':'updates/2026-10-19/'+n,'bytes':(p/n).stat().st_size,'sha256':hashlib.sha256((p/n).read_bytes()).hexdigest()} for n in files],'also_publish':'manifest.json','excluded':['baseline-evidence.jsonl','scan-run.log','supplement-run.log','isrctn-run.log'],'reproduce':'python scan_sources.py --out .; python scan_supplement.py --out .; python check_isrctn.py .; python verify_candidates.py; python build_results.py; python finalize.py. Live-source outputs can change and new records require manual review rather than blind reuse of dated decisions.'})
print(json.dumps(checks))
